import sys

data = sys.stdin.read().split()
R = int(data[0])
grid = [[int(data[1 + 5 * i + j]) for j in range(5)] for i in range(R)]

def solve(g):
    def dfs(k, c):
        if k > R:
            return 0
        best = 0
        for c2 in (c - 1, c, c + 1):
            if 0 <= c2 < 5:
                v = g[R - k][c2]
                if v == 2:
                    continue
                best = max(best, v + dfs(k + 1, c2))
        return best
    return dfs(1, 2)

ans = solve(grid)
for t in range(1, R + 1):
    g = [row[:] for row in grid]
    for step in range(t, t + 5):
        if step <= R:
            r = R - step
            g[r] = [0 if v == 2 else v for v in g[r]]
    ans = max(ans, solve(g))
print(ans)

